/**
 * Brand art for every provider Kabmo can show, one glyph per brand.
 *
 * GENERATED DATA — do not hand-edit a path. Each entry is the inner markup of a
 * brand mark, resolved to `currentColor`, with its own `viewBox` because the
 * sources do not share one.
 *
 * Sources, in the order a glyph was taken:
 *
 * 1. `@lobehub/icons-static-svg` (MIT) — official monochrome marks, 24x24.
 * 2. `simple-icons` (CC0) — used where lobehub has no entry (GitLab, Xiaomi).
 * 3. `selfh.st/icons` (CC BY 4.0) — LiteLLM, llama.cpp.
 * 4. The vendor's own SVG (favicon or logo), with any background plate dropped.
 * 5. A potrace outline of the vendor's own raster logo, refitted to fill a
 *    24x24 box — the last resort for a brand publishing no vector mark.
 *
 * Every traced glyph is refitted so its ink fills its viewBox (88% of the
 * shorter axis): a mark whose art sits small inside its own box renders smaller
 * than its neighbours at the same `size` prop, which is what made the initials
 * fallback look undersized next to them.
 *
 * `body` is inner markup only: the caller owns the `<svg>` element, so a glyph
 * inherits the surrounding ink through `currentColor` and never carries a
 * hardcoded colour. Per-element `fill-opacity`/`fill-rule`/`stroke-width`
 * survive because they are the mark's own structure (Azure's overlapping panes,
 * Cerebras' ring, Synthetic's stroked outline), not a palette choice.
 *
 * These are third-party trademarks, used here to identify the provider each one
 * belongs to. They are not covered by this project's licence.
 */

export interface ProviderGlyph {
  /** The glyph's own coordinate system — do not assume 24x24. */
  viewBox: string;
  /** Inner SVG markup, painted in `currentColor`. */
  body: string;
}

